{"code": "export async function main(input: { queries: string[] }) {
  const out: Record<string, unknown> = {};
  for (const q of input.queries) {
    const r = await sdk.linear.searchIssues({ query: q });
    out[q] = r.issues.map(i => ({ identifier: i.identifier, title: i.title, description: i.description, state: i.state }));
  }
  return out;
}", "input": {"queries": ["[Sentry] WEB-1A", "[Sentry] WEB-1B", "[Sentry]"]}}

{"code": "export async function main(input: { project: string; minEvents: number }) {
  const res = await sdk.sentry.listIssues({ project: input.project });
  const targets = res.issues.filter(i => i.status === "unresolved" && i.count >= input.minEvents);

  const created: unknown[] = [];
  const skipped: unknown[] = [];
  for (const issue of targets) {
    const title = `[Sentry] ${issue.shortId}`;
    const existing = await sdk.linear.searchIssues({ query: title });
    const dup = existing.issues.find(i => i.title === title);
    if (dup) {
      skipped.push({ shortId: issue.shortId, existing: dup.identifier });
      continue;
    }
    const p = await sdk.linear.createIssue({ title, description: issue.culprit });
    created.push({ shortId: issue.shortId, count: issue.count, title, description: issue.culprit, placeholder: p });
  }
  return { considered: targets.length, created, skipped };
}", "input": {"project": "web", "minEvents": 50}}

